ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);args=ap.parse_args();m=Compression(eta=1.,wave_R_kpc=10000.);q=Exact(J=30);s=np.load('nonlinear_transfer_2026_10_25/run_exact_equilibrium/state.npz');a=s['a'];mt=abs(a[0])**2;mf=abs(a[1])**2;mass=mt+mf;theta=np.arctan2(abs(a[0]),abs(a[1]));x=s['alpha']*2/np.pi;y=theta*2/np.pi;n=m.n;rf=(m.r[1:]+m.r[:-1])/2;L=200/m.rm;vf=rf*np.exp(-(rf/L)**4);fluxT=rf**2*.5*(mt[:-1]/m.vol[:-1]+mt[1:]/m.vol[1:])*vf;fluxF=rf**2*.5*(mf[:-1]/m.vol[:-1]+mf[1:]/m.vol[1:])*vf
def div(flux):return np.r_[0,flux]-np.r_[flux,0]
