H=torch.autograd.functional.hessian(E,T(state)).detach().numpy();tangent=np.r_[dm/mass,np.zeros(n),dy];h=H[n:2*n]@tangent;Hxx=H[n:2*n,n:2*n];dx=-np.linalg.solve(Hxx,h);tangent[n:2*n]=dx;K=float(tangent@H@tangent);v=m.r*np.exp(-(m.r/L)**4);I=float(mass@(v*v));rho=mt/m.vol;S=np.zeros(n);S[:-1]+=fluxT*(-1.5*rho[:-1]+.5*rho[1:]);S[1:]+=fluxT*(1.5*rho[1:]-.5*rho[:-1]);M=float(sum(S));D=float(sum((S*S+2*S*(np.cumsum(S)-S))/m.r));assert K>0 and D>0;Omega0=np.sqrt(K/I);eta=m.g2*m.g2/m.c**2*D/I;Omega=Omega0/np.sqrt(1+eta);rate=m.g2*m.g2*M*M*Omega**2/(m.c**3*I*(1+eta));best=M*M/D*Omega0**2/(4*m.c);out={'scope':'Linear radial coherent compression tangent at exact benchmark, both densities transported, carrier relaxed in full static Hessian, no nonlinear turbulence bound. Low-frequency compact monopole approximation.','K':K,'I':I,'source_monopole':M,'source_Poisson_norm':D,'source_charge_identity_error':float(abs(sum(S)-2*rho@dmt)),'matched_g2_actual_eta':eta,'uncoupled_period_Myr':float(2*np.pi/Omega0*m.tdyn),'coupled_period_Myr':float(2*np.pi/Omega*m.tdyn),'max_slow_rate_per_Myr':float(best/m.tdyn),'minimum_linear_energy_damping_time_Myr':float(m.tdyn/best),'matched_g2_energy_damping_time_Myr':float(m.tdyn/rate),'mode_compactness_200kpc':float(Omega*L/m.c),'derivation':'P=g2² M² Omega^4 A²/(2c³); E=I(1+eta)Omega² A²/2; Omega²=Omega0²/(1+eta). P/E=[eta/(1+eta)²](M²/D)Omega0²/c <=(M²/D)Omega0²/(4c).','non_claims':['No whole-PDE nonlinear no-go','No source-grid convergence certification','No measured formation timescale','Nonradial or incoherent short wavelength modes not covered']};Path(args.output).write_text(json.dumps(out,indent=2)+'\n');print(out)
